static bool ck(csh h,const uint8_t*b,unsigned id,const char*m,const char*o){cs_insn*i=NULL;bool ok=cs_disasm(h,b,9,0,1,&i)==1;if(ok){const cs_x86*x=&i->detail->x86;bool ac=(x->operands[0].type==X86_OP_MEM&&x->operands[0].access==CS_AC_WRITE&&x->operands[1].access==CS_AC_READ)||(x->operands[1].type==X86_OP_MEM&&x->operands[1].access==CS_AC_WRITE&&x->operands[0].access==CS_AC_READ);ok=i->id==id&&!strcmp(i->mnemonic,m)&&!strcmp(i->op_str,o)&&x->op_count==2&&ac&&x->eflags==0;}if(i)cs_free(i,1);return ok;}
int main(void){const uint8_t c[][9]={{0x64,0x62,0x0c,0xfc,8,0xf9,0x54,0xb5,0x20},{0x64,0x62,0x0c,0x7c,8,0x66,0x54,0xb5,0x20},{0x64,0x62,0x0c,0xfc,8,0x66,0x54,0xb5,0x20},{0x64,0x62,0x0c,0x7d,8,0x65,0x54,0xb5,0x20},{0x64,0x62,0x0c,0xfd,8,0x65,0x54,0xb5,0x20}};const unsigned ids[]={X86_INS_MOVDIRI,X86_INS_WRSSD,X86_INS_WRSSQ,X86_INS_WRUSSD,X86_INS_WRUSSQ};const char*mn[]={"movdiri","wrssd","wrssq","wrussd","wrussq"};const char*op[]={"qword ptr fs:[r29 + r14*4 + 0x20], r26","dword ptr fs:[r29 + r14*4 + 0x20], r26d","qword ptr fs:[r29 + r14*4 + 0x20], r26","dword ptr fs:[r29 + r14*4 + 0x20], r26d","qword ptr fs:[r29 + r14*4 + 0x20], r26"};csh h;cs_insn*i=NULL;bool ok=true;if(cs_open(CS_ARCH_X86,CS_MODE_64,&h))return 1;cs_option(h,CS_OPT_DETAIL,CS_OPT_ON);for(unsigned k=0;k<5;k++)ok&=ck(h,c[k],ids[k],mn[k],op[k]);cs_option(h,CS_OPT_SYNTAX,CS_OPT_SYNTAX_ATT);ok&=ck(h,c[0],X86_INS_MOVDIRI,"movdiriq","%r26, %fs:0x20(%r29,%r14,4)");cs_option(h,CS_OPT_SYNTAX,CS_OPT_SYNTAX_INTEL);uint8_t bad[9];memcpy(bad,c[0],9);for(unsigned k=0;k<4;k++){bad[4]=(uint8_t[]){0,4,0x18,0x28}[k];if(cs_disasm(h,bad,9,0,1,&i)){ok=false;cs_free(i,1);i=NULL;}}memcpy(bad,c[1],9);bad[5]=0x66;bad[6]=0xd3;if(cs_disasm(h,bad,7,0,1,&i)){ok=false;cs_free(i,1);}cs_close(&h);if(!ok)fprintf(stderr,"APX direct store failure\n");return ok?0:1;}
